    icon: () => <BarChart4 />,
  },
  {
    id: 'cart',
    icon: () => <Cart />,
  },
  {
    id: 'dollarsign',
    icon: () => <DollarSign />,
  },
  {
    id: 'grid',
    icon: () => <Grid />,
  },
];
